import sys
from collections import deque

def solve():
    import sys
    input = sys.stdin.read().splitlines()
    idx = 0
    results = []
    T = int(input[idx])
    idx += 1
    for _ in range(T):
        N = int(input[idx])
        idx += 1
        A = list(map(int, input[idx].split()))
        idx += 1
        used = [False] * (N + 1)
        P = [-1] * N
        stack = deque()
        for i in range(N):
            while stack and A[i] != -1 and stack[-1][0] > A[i]:
                stack.pop()
            if A[i] != -1:
                if not stack or stack[-1][0] != A[i]:
                    results.append(-1)
                    break
                P[i] = stack.pop()[1]
                used[P[i]] = True
            stack.append((i, i + 1))
        else:
            available = deque([i for i in range(1, N + 1) if not used[i]])
            for i in range(N):
                if P[i] == -1:
                    while available and used[available[0]]:
                        available.popleft()
                    if not available:
                        results.append(-1)
                        break
                    P[i] = available.popleft()
            else:
                results.append(' '.join(map(str, P)))
        if len(results) == _ + 1 and results[-1] == -1:
            continue
    for result in results:
        print(result)

solve()
